class ProfileFormScreen extends StatefulWidget {
  const ProfileFormScreen({super.key});
  @override State<ProfileFormScreen> createState() => _ProfileFormScreenState();
}

class _ProfileFormScreenState extends State<ProfileFormScreen> {
  static const conditions = ['None', 'Diabetes', 'Hypertension', 'PCOS', 'Obesity / Weight Management', 'Pregnancy', 'Other'];
  static const activities = ['Sedentary', 'Lightly Active', 'Moderately Active', 'Very Active'];
  static const goals = ['Weight Loss', 'Weight Maintenance', 'Weight Gain', 'Muscle Gain', 'General Healthy Eating'];
  static const preferences = ['Vegetarian', 'Non-Vegetarian', 'Vegan', 'Eggetarian', 'Other'];
  static const allergies = ['Peanut', 'Milk', 'Egg', 'Soy', 'Gluten', 'Other'];
  static const sexes = ['Female', 'Male', 'Intersex', 'Prefer not to say'];
  final formKey = GlobalKey<FormState>(); final name = TextEditingController(); final age = TextEditingController(); final height = TextEditingController(); final weight = TextEditingController(); final api = ProfileApiService();
  final selectedConditions = <String>{}; final selectedAllergies = <String>{}; String? sex, activity, goal, preference; bool loading = true, saving = false, exists = false;
  @override void initState() { super.initState(); load(); }
  @override void dispose() { name.dispose(); age.dispose(); height.dispose(); weight.dispose(); super.dispose(); }
  Future<void> load() async { try { final p = await api.fetchProfile(); if (!mounted) return; if (p != null) { name.text = p.name; age.text = '${p.age}'; height.text = '${p.heightCm}'; weight.text = '${p.weightKg}'; sex = p.sex; activity = p.activityLevel; goal = p.primaryGoal; preference = p.dietaryPreference; selectedConditions.addAll(p.healthConditions); selectedAllergies.addAll(p.allergies); exists = true; } setState(() => loading = false); } on ProfileApiException catch (e) { if (mounted) { setState(() => loading = false); message(e.message); } } }
  Future<void> save() async { if (!(formKey.currentState?.validate() ?? false)) return; if ([sex, activity, goal, preference].contains(null)) { message('Please complete all required selections.'); return; } final p = UserProfile(name: name.text.trim(), age: int.parse(age.text), sex: sex!, heightCm: double.parse(height.text), weightKg: double.parse(weight.text), healthConditions: selectedConditions.toList(), activityLevel: activity!, primaryGoal: goal!, dietaryPreference: preference!, allergies: selectedAllergies.toList()); setState(() => saving = true); try { await (exists ? api.updateProfile(p) : api.createProfile(p)); if (mounted) { setState(() { saving = false; exists = true; }); message('Profile saved successfully.', success: true); } } on ProfileApiException catch (e) { if (mounted) { setState(() => saving = false); message(e.message); } } }
  void message(String text, {bool success = false}) => ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(text), backgroundColor: success ? AppTheme.primaryGreen : Colors.red.shade700));
  String? number(String? v, String label, double min, double max, {bool whole = false}) { final n = double.tryParse(v ?? ''); return n == null || n < min || n > max || (whole && n != n.roundToDouble()) ? '$label must be between ${min.toInt()} and ${max.toInt()}.' : null; }
