else { selectedConditions.remove('None'); if (on) selectedConditions.add(v); else selectedConditions.remove(v); } }))]), section('Activity level', [chips(activities, {if (activity != null) activity!}, (v, on) => setState(() => activity = v))]), section('Fitness / nutrition goal', [chips(goals, {if (goal != null) goal!}, (v, on) => setState(() => goal = v))]), section('Dietary preference', [chips(preferences, {if (preference != null) preference!}, (v, on) => setState(() => preference = v))]), section('Food allergies / intolerances', [chips(allergies, selectedAllergies, (v, on) => setState(() => on ? selectedAllergies.add(v) : selectedAllergies.remove(v)))]), FilledButton.icon(onPressed: saving ? null : save, icon: saving ? const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white)) : const Icon(Icons.save_outlined), label: Text(saving ? 'Saving...' : exists ? 'Update profile' : 'Save profile'), style: FilledButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 16))), const SizedBox(height: 12), OutlinedButton.icon(onPressed: () async { await AuthService().logout(); if (mounted) Navigator.of(context).pushAndRemoveUntil(MaterialPageRoute(builder: (_) => const LoginScreen()), (_) => false); }, icon: const Icon(Icons.logout_rounded), label: const Text('Logout'), style: OutlinedButton.styleFrom(foregroundColor: Colors.redAccent))]))); }
  Widget section(String title, List<Widget> body) => Card(margin: const EdgeInsets.only(bottom: 16), child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 16)), const SizedBox(height: 14), ...body])));
  Widget dropdown(String label, String? value, List<String> values, ValueChanged<String?> changed) => DropdownButtonFormField<String>(value: value, isExpanded: true, decoration: InputDecoration(labelText: label), items: values.map((v) => DropdownMenuItem(value: v, child: Text(v))).toList(), onChanged: changed, validator: (v) => v == null ? 'Please select $label.' : null);
  Widget chips(List<String> options, Set<String> selected, void Function(String, bool) changed) => Wrap(spacing: 8, runSpacing: 8, children: options.map((v) => FilterChip(label: Text(v), selected: selected.contains(v), onSelected: (on) => changed(v, on))).toList());
}
